INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 15, 'theory', 'Quiz: exceptions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 0, 'Which line of a traceback holds the most important information about the error?', '["The first", "The very last: the error type and message", "The middle one", "There is no such line"]', 1, 'A traceback is read from the bottom up: the last line names the error type and the message.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 1, 'try: int("abc") / except ValueError: print("x") / else: print("y") / finally: print("z"). What gets printed?', '["x and z", "y and z", "only x", "x, y and z"]', 0, 'There was an error, so except ran (x); else does not run; finally always runs (z).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 2, 'What does a bare raise do inside an except block?', '["Creates a new empty error", "Passes the same exception on, keeping the traceback", "Stops the interpreter", "Nothing"]', 1, 'A raise with no arguments re-raises the caught exception along with its whole traceback.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 3, 'How do you create your own exception?', '["def MyError(): ...", "class MyError(Exception): pass", "raise MyError", "import MyError"]', 1, 'A custom exception is an ordinary class that inherits from Exception.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 15, 4, 'Why should user data not be validated with assert?', '["assert is slow", "assert is turned off when Python runs with optimization", "assert does not raise errors", "assert works only with numbers"]', 1, 'Running python -O strips all asserts; input data is validated with raise and a real exception.');
